#include <iostream>
#include <cmath>
#include <vector>
#include <cstddef>

bool convertir_entero(double origen, int& destino) {
    if (!std::isfinite(origen) || origen < -100.0 || origen > 100.0) {
        return false;
    }
    const int candidato = static_cast<int>(origen);
    const double vuelta = static_cast<double>(candidato);
    if (vuelta != origen) {
        return false;
    }
    destino = candidato;
    return true;
}

int main() {
    std::vector<double> origen{-100.0, -2.5, 0.0, 4.0, 100.0, 101.0};
    const std::vector<double> copia = origen;
    std::vector<int> enteros;
    int rechazados{0};
    int ceros{0};
    for (const double dato : origen) {
        int destino{17};
        const bool aceptado = convertir_entero(dato, destino);
        if (aceptado) {
            enteros.push_back(destino);
            if (destino == 0) {
                ++ceros;
            }
        } else {
            ++rechazados;
        }
    }
    bool conservados = origen.size() == copia.size();
    if (conservados) {
        for (std::size_t i{0}; i < origen.size(); ++i) {
            if (origen.at(i) != copia.at(i)) {
                conservados = false;
            }
        }
    }
    std::cout << "Entiers :";
    for (const int valor : enteros) {
        std::cout << valor << ";";
    }
    std::cout << "\nRejetés : " << rechazados
              << "\nZéros acceptés : " << ceros
              << "\nDonnées conservées : " << conservados << "\n";
    return 0;
}

